  ui_story_5065_50650101_2_dialog_content = "Bom dia. Você é Paloma, o estagiário recomendado pela Academia Dawn?",
  ui_story_5065_50650101_3_dialog_content = "Sim, mas as pessoas geralmente me chamam de Pam. Sou grato à Academia e ao Templo de Lumópolis por essa valiosa oportunidade de treinamento!",
  ui_story_5065_50650101_4_dialog_content = "Pam, você sabe qual é o propósito do Templo de Lumópolis?",
