  ui_story_5065_50650102_19_dialog_content = "Há uma gangue de encrenqueiros da Baixa Lumópolis, roubando objetos valiosos de várias casas nobres, e eles ainda estão escondidos em Lumópolis!",
  ui_story_5065_50650102_20_dialog_content = "Infelizmente, não consegui capturá-los, então este caso ainda está na minha mesa, afetando seriamente minha avaliação de desempenho...",
