  ui_story_5065_50650102_30_dialog_content = "Paloma, hora de partir! Na próxima vez que nos encontrarmos, espero ver você trazendo os ladrões que capturou.",
  ui_story_5065_50650103_1_dialog_content = "Saudações! Perdoe-me, mas você viu alguma pessoa suspeita hoje?",
  ui_story_5065_50650103_2_dialog_content = "P-Pessoas suspeitas? Acho que não tem nenhuma...",
  ui_story_5065_50650103_3_dialog_content = "Desc.",
  ui_story_5065_50650103_4_dialog_content = "(Estranho, não deveria ser hora de os guardas trocarem de turno, então por que esse guarda está fazendo o que quer?)",
  ui_story_5065_50650103_5_dialog_content = "(Não (Não, autoc Alonsoir, and other examples of, and the like.",
