  ui_story_5065_50650104_2_dialog_content = "Vossa Honra, capturei um dos suspeitos! Ele estava se passando por um Guarda Lumo e quase escapou em um navio aéreo!",
  ui_story_5065_50650104_3_dialog_content = "Você? Pegou eles? O fugitivo? Isso é... inacreditável...",
  ui_story_5065_50650104_4_dialog_content = "Ah não, o que eu quis dizer foi, você não acha que essa missão é bem simples?",
  ui_story_5065_50650104_5_dialog_content = "Solte-me! Você tem alguma prova?!",
  ui_story_5065_50650104_6_dialog_content = "Evidência? Isso não é algo que você pode plantar o quanto quiser?",
  ui_story_5065_50650104_7_dialog_content = "O que quer dizer com isso, senhor...?",
  ui_story_5065_50650104_8_dialog_content = "Aham, quer dizer, vou interrogar esse ladrão minuciosamente, fazendo-o confessar e enfrentar as consequências.",
  ui_story_5065_50650104_9_dialog_content = "<lock-locked>, apenas assistice, </lock_0 a 3 not.",
  ui_story_5065_50650104_10_dialog_content = "Mas...",
  ui_story_5065_50650104_11_dialog_content = "Mas o quê? Não pense que pegar um ladrão te dá o direito de fazer pedidos insolentes na minha frente.",
  ui_story_5065_50650104_12_dialog_content = "Mas o ladrão conseguiu se soltar das algemas e escapou!",
  ui_story_5065_50650104_13_dialog_content = "Vá, sempre carefully of the same time, Vá atrás",
  ui_story_5065_50650104_14_dialog_content = "Isso é ultrajante!",
  ui_story_5065_50650104_15_dialog_content = "Senhor, consegui prender o ladrão novamente, então por favor não fique chateado! Devemos usar mais de um par de algemas nele?",
  ui_story_5065_50650104_16_dialog_content = "Hmph, não precisa. Vou trancá-lo diretamente na prisão!",
  ui_story_5065_50650104_17_dialog_content = "Você se saiu bem hoje, não decepcionou. Mas eu vou cuidar disso daqui pra frente; você não precisa se preocupar.",
  ui_story_5065_50650201_1_dialog_content = "Suspiro... Isso não é bom...",
  ui_story_5065_50650201_2_dialog_content = "O que aconteceu, Meritíssimo? Há algo em que eu possa ajudar?",
  ui_story_5065_50650201_3_dialog_content = "Ah, você chegou bem na hora! É minha vez hoje de abrir a porta do escritório antes de todos os outros chegarem.",
  ui_story_5065_50650201_4_dialog_content = "Mas a chave do escritório foi engolida pelo peixe no lago!",
  ui_story_5065_50650201_5_dialog_content = "Um peixe engoliu a chave? Espero que esteja bem...",
  ui_story_5065_50650201_6_dialog_content = "Há tantos peixes e não consigo saber qual... Espere, você não deveria estar mais preocupado comigo?",
  ui_story_5065_50650201_7_dialog_content = "E-Eu quis dizer, você está bem, senhor?",
  ui_story_5065_50650201_8_dialog_content = "Pareço estar bem? Tenho que abrir o escritório antes de todos chegarem, ou minha avaliação de desempenho deste mês vai... Ahem... De qualquer forma, tenho uma tarefa para você.",
  ui_story_5065_50650201_9_dialog_content = "Dawn Academia, Pátio de Lumopolis e Baixa Lumopolis têm cada um uma escultura em escala. Eles se parecem exatamente com o que está em frente ao Hall of Justice.",
  ui_story_5065_50650201_10_dialog_content = "Pssiu! Mantenha isso entre nós... Se você completar a missão da balança, ela vai soltar um Peso Dourado.",
  ui_story_5065_50650201_11_dialog_content = "Desde que você colete os pesos dourados das três diferentes esculturas de balança, pode combiná-los na balança em frente ao Salão da Justiça para criar uma chave!",
  ui_story_5065_50650201_12_dialog_content = "Sua tarefa é ir e me ajudar a coletar esses três pesos dourados.",
  ui_story_5065_50650201_13_dialog_content = "Você não vem comigo, senhor?",
  ui_story_5065_50650201_14_dialog_content = "Bem, tenho outras coisas para cuidar... Sabe, caso alguém apareça, terei que encontrar uma desculpa para mandá-los embora.",
  ui_story_5065_50650201_15_dialog_content = "Andando! Se apresse!",
  ui_story_5065_50650202_1_dialog_content = "Realmente saiu um peso dourado!",
  ui_story_5065_50650202_2_dialog_content = "Graças ao conhecimento acumulado ao longo dos dias, essas missões não são difíceis.",
  ui_story_5065_50650202_3_dialog_content = "Nesse ritmo, devo chegar a tempo... Preciso me apressar para o próximo conjunto de balanças!",
  ui_story_5065_50650203_1_dialog_content = "  , Goldie!\nTranslation:É outro peso, Goldie!\n\nText:Goldie 3.0\nTranslation:Goldie 3.0\n\nText:Goldie, you're the best!\nTranslation:Goldie, você é o melhor!",
  ui_story_5065_50650203_2_dialog_content = "Isso é ótimo, agora só preciso de mais um e o conjunto estará completo.",
  ui_story_5065_50650204_1_dialog_content = "Finalmente coletei os três pesos dourados!",
  ui_story_5065_50650204_2_dialog_content = "Consigo chegar a tempo? Devo me apressar e entregar isso ao Juiz Júnior...",
  ui_story_5065_50650205_1_dialog_content = "*roncando*",
  ui_story_5065_50650205_2_dialog_content = "Não estou muito atrasado, estou, senhor?",
  ui_story_5065_50650205_3_dialog_content = "Hã?! A chave do escritório foi levada por aquele estagiário chamado Paloma!",
  ui_story_5065_50650205_4_dialog_content = "Ah, desculpe se te acordei, senhor, mas eu nunca peguei a chave...",
  ui_story_5065_50650205_5_dialog_content = "Ahem, é você, né? Pensei que fosse um dos meus colegas. Você terminou a tarefa que lhe dei?",
  ui_story_5065_50650205_6_dialog_content = "Se você não conseguir trazer de volta três pesos dourados, eu não poderei obter a chave. Então, não seria um exagero dizer que você tirou a chave, certo?",
  ui_story_5065_50650205_7_dialog_content = "Trouxe de volta os três pesos dourados que você pediu.",
  ui_story_5065_50650205_8_dialog_content = "Você... quer dizer que você realmente completou essas missões?",
  ui_story_5065_50650205_9_dialog_content = "O trainee acabou de completar as missões que nem mesmo eu consegui lidar?",
  ui_story_5065_50650205_10_dialog_content = "Quer dizer... não há como negar que meu julgamento de pessoas parece estar certíssimo!",
  ui_story_5065_50650205_11_dialog_content = "Não se preocupe. Vou falar bem de você para o seu mentor.",
  ui_story_5065_50650205_12_dialog_content = "Obrigado pelo seu apoio, Juiz Júnior!",
  ui_story_5065_50650301_1_dialog_content = "Bom dia, Meritíss in your health and the health,...",
  ui_story_5065_50650301_2_dialog_content = "Bem, Pam, eu estive esperando por você.",
  ui_story_5065_50650301_3_dialog_content = "D-Desculpe... Estou atrasado de novo?",
  ui_story_5065_50650301_4_dialog_content = "Você perdeu o emocionante momento do meu interrogatório com o ladrão, mas tudo bem. Saiba apenas que...",
  ui_story_5065_50650301_5_dialog_content = "... após meu brilhante interrogatório, o ladrão que pegamos há alguns dias finalmente revelou o paradeiro de seus cúmplices!",
  ui_story_5065_50650301_6_dialog_content = "Noite Branca lá no alto! Como você fez isso?! Ele não nos deu uma única pista nos últimos dias!",
  ui_story_5065_50650301_7_dialog_content = "Hunf, se você quer saber, posso te ensinar mais tarde.",
  ui_story_5065_50650301_8_dialog_content = "Agora, precisamos aproveitar nossa vantagem e capturar o resto dos ladrões!",
  ui_story_5065_50650301_9_dialog_content = "Esses criminosos miseráveis estarão esperando por um encontro perto da escultura em escala no Pátio de Lumópolis hoje. Apresse-se e detenha-os!",
  ui_story_5065_50650301_10_dialog_content = "Como desejar, Meritíssimo!",
  ui_story_5065_50650302_1_dialog_content = "Usando os mesmos disfarces de novo, hein?",
  ui_story_5065_50650302_2_dialog_content = "Quem é você?! Como ousa desrespeitar os guardas de Lumópolis?",
  ui_story_5065_50650302_3_dialog_content = "Eu... Eu não vou deixar você manchar o nome dos guardas da nossa cidade por mais tempo!",
  ui_story_5065_50650303_1_dialog_content = "Meritíssimo, trouxe de volta o cúmplice do ladrão!",
  ui_story_5065_50650303_2_dialog_content = "Como é que só tem um deles?!",
  ui_story_5065_50650303_3_dialog_content = "B-Bem, eu só notei uma pessoa suspeita no Pátio de Lumópolis.",
  ui_story_5065_50650303_4_dialog_content = "Por que você só verificou o Pátio de Lumopolis? Já está começando a relaxar, hein?",
  ui_story_5065_50650303_5_dialog_content = "Não mencionei que havia outro cúmplice escondido na Baixa Lumópolis?",
  ui_story_5065_50650303_6_dialog_content = "F-Falou isso, senhor?",
  ui_story_5065_50650303_7_dialog_content = "Uau, ao primeiro sinal de problema, você já está tentando jogar a culpa no seu superior? Por que não considerar se você se lembrou errado?",
  ui_story_5065_50650303_8_dialog_content = "Tão jovem e já adotando essas práticas ruins. Quem sabe o que o futuro reserva para você?",
  ui_story_5065_50650303_9_dialog_content = "Desculpe. É possível que eu realmente não esteja me lembrando das coisas corretamente...",
  ui_story_5065_50650303_10_dialog_content = "Mas não se preocupe, senhor, vou descer até a Baixa Lumópolis e prender os criminosos restantes imediatamente!",
  ui_story_5065_50650304_1_dialog_content = "Outro guarda solitário olhando ao redor com suspeita...",
  ui_story_5065_50650304_2_dialog_content = "Ele pode estar disfarçado de guarda de Lumópolis, mas não há como esconder sua intenção criminosa.",
  ui_story_5065_50650304_3_dialog_content = "O-o que você está fazendo?!",
  ui_story_5065_50650304_4_dialog_content = "Levando você ao lugar onde pertence.",
  ui_story_5065_50650305_1_dialog_content = "Hmm, isso está certo.",
  ui_story_5065_50650305_2_dialog_content = "Considerando que você reuniu todos os cúmplices do ladrão, posso deixar esse incidente desagradável passar hoje.",
  ui_story_5065_50650305_3_dialog_content = "Obrigado por ser tão compreensivo, Meritíssimo!",
  ui_story_5065_50650305_4_dialog_content = "Há algo mais que eu possa fazer para ajudá-lo?",
  ui_story_5065_50650305_5_dialog_content = "Os próximos julgamentos são bem diferentes de capturar criminosos; eles exigem maior inteligência e habilidade.",
  ui_story_5065_50650305_6_dialog_content = "Mesmo que eu te conte os truques, você não vai entendê-los em pouco tempo. Além disso, um estagiário não precisa se envolver em questões excessivamente complexas.",
  ui_story_5065_50650305_7_dialog_content = "I-É mesmo...? Mas senhor, se você me der uma chance, eu prometo que não vou te decepcionar!",
  ui_story_5065_50650305_8_dialog_content = "Já chega por hoje. Você não está cansado ainda? Volte, e eu cuidarei do resto!",
  ui_story_5065_50650305_9_dialog_content = "Huh? Você está demonstrando consideração me mandando para casa para descansar?",
  ui_story_5065_50650305_10_dialog_content = "Huh? Ahn, aham... Sim, é exatamente isso que eu quis dizer.",
  ui_story_5065_50650305_11_dialog_content = "Muito obrigado, senhor!",
  ui_story_5065_50650305_12_dialog_content = "Você estava certo. O sonho de Paloma se entrelaçou com o meu...",
  ui_story_5065_50650305_13_dialog_content = "Para ser mais preciso, a pessoa que está aqui e se recusa a acordar é a Pam que você conheceu no seu sonho.",
  ui_story_5065_50650305_14_dialog_content = "Pam... Ela está sonhando com o tempo em que se tornou trainee pela primeira vez?",
  ui_story_5065_50650305_15_dialog_content = "Esse foi o período mais feliz da vida dela.",
  ui_story_5065_50650305_16_dialog_content = "Tenho que contar a verdade para a Pam? Não suporto estragar a felicidade dela...",
  ui_story_5065_50650305_17_dialog_content = "Mas se ela não acordar, você também não terá como acordar.",
  ui_story_5065_50650305_18_dialog_content = "Pam, você foi quem me ajudou a perceber que esse sonho não passava de uma ilusão. No final, todos nós precisamos acordar e encarar nossos verdadeiros eus.",
  ui_story_5065_50650305_19_dialog_content = "Dessa vez, é minha vez de te acordar.",
  ui_story_5065_50650401_1_dialog_content = "Bom dia, Meritíssimo!",
  ui_story_5065_50650401_2_dialog_content = "Ah, Pam, você chegou bem na hora.",
  ui_story_5065_50650401_3_dialog_content = "Acabei de perceber que tenho alguns livros emprestados da Dawn Academy aqui, e estão perto da data de devolução.",
  ui_story_5065_50650401_4_dialog_content = "Ajude-me a devolvê-los e depois pegar alguns dos mesmos livros emprestados.",
  ui_story_5065_50650401_5_dialog_content = "Você está dizendo... Que quer continuar pegando esses livros emprestados?",
  ui_story_5065_50650401_6_dialog_content = "Não, já renovei esses livros dez vezes e não posso renová-los mais.",
  ui_story_5065_50650401_7_dialog_content = "Que bom que a Dawn Academy tem várias cópias dos mesmos livros. Por favor, pegue algumas cópias diferentes para mim.",
  ui_story_5065_50650401_8_dialog_content = "Entendi... Eu me pergunto que tipos de livros justificam dez renovações seguidas?",
  ui_story_5065_50650401_9_dialog_content = "\"O Espírito do Debate Jurídico\", \"Panorama do Direito\"... Esses livros parecem tão esotéricos! Sobre o que exatamente eles discutem?",
  ui_story_5065_50650401_10_dialog_content = "Bem, ah... se você quiser saber, eu posso escrever um resumo para você, mas pode levar algum tempo.",
  ui_story_5065_50650401_11_dialog_content = "Vá buscá-los para mim agora mesmo.",
  ui_story_5065_50650401_12_dialog_content = "Muito bem, deixe comigo!",
  ui_story_5065_50650402_1_dialog_content = "Esses livros são muito mais pesados do que parecem...",
  ui_story_5065_50650402_2_dialog_content = "Ufa! Graças a Deus estou quase na biblioteca! Só mais um pouquinho agora!",
  ui_story_5065_50650402_3_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5065_50650402_4_dialog_content = "Ah não... sinto muito!",
  ui_story_5065_50650402_5_dialog_content = "Eu estava correndo tão rápido que não te notei ali... Você está bem?",
  ui_story_5065_50650402_6_dialog_content = "(Essas foram minhas palavras quando conheci a Pam pela primeira vez. Será que ela ainda se lembra?)",
  ui_story_5065_50650402_7_dialog_content = "Ai...",
  ui_story_5065_50650402_8_dialog_content = "E-Estou bem. Por favor, não se culpe, senhora cavaleira.",
  ui_story_5065_50650402_9_dialog_content = "(A Pam disse exatamente a mesma coisa naquela época também!)",
  ui_story_5065_50650402_10_dialog_content = "Eu também estava com pressa e não consegui prestar atenção ao meu redor...",
  ui_story_5065_50650402_11_dialog_content = "Se for o caso, eu deveria ser o único a me desculpar!",
  ui_story_5065_50650402_12_dialog_content = "(A maneira como ela está olhando para mim... É como se estivesse olhando para um completo estranho.)",
  ui_story_5065_50650402_13_dialog_content = "Você realmente não se lembra de quem eu sou?",
  ui_story_5065_50650402_14_dialog_content = "Er... A julgar pela sua roupa, posso supor que você é um Cavaleiro da Justiça?",
  ui_story_5065_50650402_15_dialog_content = "Algo em você parece familiar, sim. Já nos vimos no Tribunal de Justiça antes?",
  ui_story_5065_50650402_16_dialog_content = "Eu sou Irridon, a pessoa de quem você deseja se vingar... Você não se lembra de nada disso?",
  ui_story_5065_50650402_17_dialog_content = "Desde jovem, sempre abracei os ensinamentos do Deus da Luz. Eu nunca buscaria vingança contra os outros facilmente...",
  ui_story_5065_50650402_18_dialog_content = "Pare de se entregar a essa fantasia! É tudo mentira, agora acorde!!",
  ui_story_5065_50650402_19_dialog_content = "É... Tem certeza de que não está me confundindo com outra pessoa?",
  ui_story_5065_50650402_20_dialog_content = "Perdoe-me, mas estou em um recado importante. Não posso ficar aqui por mais tempo, mas rezo para que você encontre a pessoa que está procurando.",
  ui_story_5065_50650403_1_dialog_content = "Não, eu deveria ser o único a pedir desculpas. Eu derrubei seus livros das suas mãos, então pelo menos deixe-me ajudá-lo a pegá-los.",
  ui_story_5065_50650403_2_dialog_content = "Tudo bem, eu posso reunir tudo rapidamente sozinho!",
  ui_story_5065_50650403_3_dialog_content = "Quem quer que você esteja procurando deve ser muito importante para você, certo? Por favor, não atrase sua busca por minha causa.",
  ui_story_5065_50650403_4_dialog_content = "...",
  ui_story_5065_50650404_1_dialog_content = "Suspiro, quem deixou todos esses pedaços de papel espalhados pelo pátio do campus? Se ninguém vai limpar isso, então acho que cabe a mim...",
  ui_story_5065_50650404_2_dialog_content = "Pam...",
  ui_story_5065_50650404_3_dialog_content = "Senhora Irridon?",
  ui_story_5065_50650404_4_dialog_content = "Finalmente você se lembra de mim?!",
  ui_story_5065_50650404_5_dialog_content = "... Você acabou de se apresentar para mim há alguns minutos atrás.",
  ui_story_5065_50650404_6_dialog_content = "O trabalho de um Cavaleiro da Justiça deve ocupar a maior parte do dia, não é? Por que você tem me seguido todo esse tempo?",
  ui_story_5065_50650404_7_dialog_content = "Eu... Eu ainda não me desculpei direito por ter esbarrado em você mais cedo.",
  ui_story_5065_50650404_8_dialog_content = "Gostaria de ajudá-lo... Se não for limpando essa bagunça, então devolvendo seus livros para você. Tudo bem?",
  ui_story_5065_50650404_9_dialog_content = "Eu não poderia incomodá-lo com algo tão simples como limpeza, mas se você insistir em me ajudar...",
  ui_story_5065_50650404_10_dialog_content = "Você poderia devolver esses livros e, em seguida, pegar um exemplar diferente de cada um novamente?",
  ui_story_5065_50650404_11_dialog_content = "Sim claro!",
  ui_story_5065_50650405_1_dialog_content = "Aqui estão os livros que você pediu, Pam.",
  ui_story_5065_50650405_2_dialog_content = "Obrigado, Senhora Irridon!",
  ui_story_5065_50650405_3_dialog_content = "Hmm? \"Sonhos e Realidade\", \"O Despertar\", \"Como Evitar Ser Vítima dos Seus Sonhos\"...?",
  ui_story_5065_50650405_4_dialog_content = "Esses claramente não são os livros que eu pedi!",
  ui_story_5065_50650405_5_dialog_content = "Pam, por favor! O mundo ao nosso redor não é o mundo real, é apenas um sonho! Seu sonho!",
  ui_story_5065_50650405_6_dialog_content = "Se continuarmos presos aqui... Nossos verdadeiros eus vão gradualmente perder a sanidade até morrermos de vez!",
  ui_story_5065_50650405_7_dialog_content = "Por favor, pare de mentir para si mesmo! Abra os olhos e veja o mundo como ele realmente é!",
  ui_story_5065_50650405_8_dialog_content = "O que exatamente você quer de mim? Desde que nos esbarramos, você não fez nada além de dizer as coisas mais estranhas.",
  ui_story_5065_50650405_9_dialog_content = "Eu não entendo suas palavras, nem quero...",
  ui_story_5065_50650405_10_dialog_content = "Agora, se me dão licença, tenho assuntos urgentes para tratar. Assuntos que também são muito importantes para mim.",
  ui_story_5065_50650405_11_dialog_content = "Em nome do Deus da Luz, peço que não me incomode mais. Avante, Noite Branca e bom dia para você.",
  ui_story_5065_50650405_12_dialog_content = "Mas essas tarefas são completamente sem sentido para você, Pam!",
  ui_story_5065_50650405_13_dialog_content = "Senhora Irridon, posso perceber só de olhar que você vem de uma família nobre, então talvez você não entenda...",
  ui_story_5065_50650405_14_dialog_content = "Mas tornar-me um iniciante tem sido um desafio muito difícil para mim. Se eu quiser realizar meus sonhos, devo completar essas tarefas com perfeição e da melhor forma possível.",
  ui_story_5065_50650405_15_dialog_content = "Como você pode afirmar que isso não significa nada para mim?",
  ui_story_5065_50650405_16_dialog_content = "Se você realmente pretende me impedir... E-Então não tenho escolha a não ser ser mais firme!",
  ui_story_5065_50650406_1_dialog_content = "Perdoe-me, Meritíssimo... Encontrei alguns obstáculos ao realizar minhas tarefas.",
  ui_story_5065_50650406_2_dialog_content = "Eu poderia ter devolvido seus livros mais cedo.",
  ui_story_5065_50650406_3_dialog_content = "Tudo bem; eu não vou lê-los mesmo...",
  ui_story_5065_50650406_4_dialog_content = "O que eu quero dizer é que não estou com pressa para lê-los.",
  ui_story_5065_50650406_5_dialog_content = "Entendo...",
  ui_story_5065_50650501_1_dialog_content = "Bom dia, Meritíssimo!",
  ui_story_5065_50650501_2_dialog_content = "Bom dia!",
  ui_story_5065_50650501_3_dialog_content = "Quais tarefas você tem para mim hoje, senhor?",
  ui_story_5065_50650501_4_dialog_content = "Missão? Ah, você... você tem me ajudado a pegar aqueles ladrões recentemente?",
  ui_story_5065_50650501_5_dialog_content = "Sim, senhor! Conquistar sua confiança no meu primeiro dia como estagiário e ajudá-lo a resolver casos importantes como este tem sido uma grande honra para mim!",
  ui_story_5065_50650501_6_dialog_content = "Haha, você tem sido uma grande ajuda. Graças a você, meu trabalho tem corrido bem ultimamente.",
  ui_story_5065_50650501_7_dialog_content = "Esses ladrões têm outros cúmplices à solta?",
  ui_story_5065_50650501_8_dialog_content = "Outros cúmplices? Acho que não. Não se preocupe com isso.",
  ui_story_5065_50650501_9_dialog_content = "Além disso, não está acontecendo muita coisa aqui agora. Você pode voltar. Obrigado por esses dias.",
  ui_story_5065_50650501_10_dialog_content = "Er, mas Meritíssimo...",
  ui_story_5065_50650501_11_dialog_content = "Existe algo mais?",
  ui_story_5065_50650501_12_dialog_content = "N-Não senhor, só percebi que você parece muito mais gentil do que o normal hoje.",
  ui_story_5065_50650501_13_dialog_content = "Mas agora eu finalmente entendo! Você estava apenas interpretando o papel de um instrutor rigoroso nos últimos dias!",
  ui_story_5065_50650501_14_dialog_content = "Porque apenas um instrutor rigoroso pode produzir alunos exemplares! Muito obrigado por me orientar tão bem...",
  ui_story_5065_50650501_15_dialog_content = "Huh? N-não precisa me agradecer, hahaha...",
  ui_story_5065_50650501_16_dialog_content = "Embora tenha sido breve, sempre vou valorizar o tempo que passei trabalhando sob sua orientação, Juiz Júnior!",
  ui_story_5065_50650502_1_dialog_content = "Bom dia, instrutor!",
  ui_story_5065_50650502_2_dialog_content = "Pam? 2021, about the Hall U.S. on the 3rd of November, 2018., if you want languishing in the city, and the 3rd of November, 2018, in the city, and the 3,, 2018, if that the 3rd of November, 2018, if you will, and the 3rd of November, 2018, if you will, and the 3rd stretch Maestro,,  mont tied the knot in, in the city, and,  5.0 ",
  ui_story_5065_50650502_3_dialog_content = "Concluí as tarefas iniciantes que me foram dadas pelo Tribunal de Justiça, então o Juiz Júnior permitiu que eu voltasse mais cedo.",
  ui_story_5065_50650502_4_dialog_content = "Juiz Júnior, é isso mesmo?",
  ui_story_5065_50650502_5_dialog_content = "Hum?",
  ui_story_5065_50650502_6_dialog_content = "(O que o Juiz Júnior está fazendo aqui também?)",
  ui_story_5065_50650502_7_dialog_content = "(Ahhh... Eu estava tão emocionada quando nos despedimos mais cedo, então vê-lo novamente tão cedo parece um pouco estranho.)",
  ui_story_5065_50650502_8_dialog_content = "Eu nunca disse à Pam que a missão estava concluída, não é?",
  ui_story_5065_50650502_9_dialog_content = "Hã? Mas lá no Tribunal de Justiça, você disse...",
  ui_story_5065_50650502_10_dialog_content = "Eu nem fui ao Tribunal de Justiça hoje! Ah, entendi o que está acontecendo aqui; você está tentando faltar ao trabalho, não está?",
  ui_story_5065_50650502_11_dialog_content = "E aqui estava eu, vindo conhecer seu mentor, na esperança de estender seu tempo como estagiário no Tribunal de Justiça.",
  ui_story_5065_50650502_12_dialog_content = "Caramba, realmente não dá para julgar as pessoas pela aparência hoje em dia, especialmente os mais jovens.",
  ui_story_5065_50650502_13_dialog_content = "Parece que terei que ir atrás pessoalmente do líder da gangue de ladrões.",
  ui_story_5065_50650502_14_dialog_content = "O-O que você disse?!",
  ui_story_5065_50650502_15_dialog_content = "Então a pessoa com quem falei no Tribunal de Justiça...",
  ui_story_5065_50650502_16_dialog_content = "Ah não!!!",
  ui_story_5065_50650502_17_dialog_content = "Precisamos voltar e deter aquele homem!",
  ui_story_5065_50650503_1_dialog_content = "Guardas, onde foram confinados os ladrões que prendemos há alguns dias?",
  ui_story_5065_50650503_2_dialog_content = "Pretende interrogá-los? Por favor, venha comigo.",
  ui_story_5065_50650503_3_dialog_content = "Espere!",
  ui_story_5065_50650503_4_dialog_content = "Você de novo? Por que está de volta aqui?",
  ui_story_5065_50650503_5_dialog_content = "Você não vai interrogar esses ladrões! Você vai libertá-los, não é?!",
  ui_story_5065_50650503_6_dialog_content = "Você... Você tem audácia! Apenas um aprendiz e se atreve a me questionar?",
  ui_story_5065_50650503_7_dialog_content = "Porque eu não vim aqui sozinho.",
  ui_story_5065_50650503_8_dialog_content = "O quê?",
  ui_story_5065_50650503_9_dialog_content = "Ao se passar por um membro importante do Tribunal de Justiça, você está adicionando mais uma acusação à sua lista.",
  ui_story_5065_50650503_10_dialog_content = "(!!!)",
  ui_story_5065_50650503_11_dialog_content = "Guardas, prendam o ladrão à sua frente!",
  ui_story_5065_50650503_12_dialog_content = "Avante, Noite Branca, não consigo acreditar que esses ladrões foram tão astutos...",
  ui_story_5065_50650503_13_dialog_content = "É tudo graças a você que consegui resolver este caso tranquilamente.",
  ui_story_5065_50650503_14_dialog_content = "Eu queria que você ficasse um pouco mais no Tribunal de Justiça, mas seu mentor era totalmente contra isso.",
  ui_story_5065_50650503_15_dialog_content = "Já estou com saudades dos dias em que você trabalhava para mim...",
  ui_story_5065_50650503_16_dialog_content = "Suspiro... Continue assim! Se tiver a chance, não deixe de se candidatar a uma posição no Tribunal de Justiça!",
  ui_story_5065_50650503_17_dialog_content = "Muito obrigado por confiar em mim, Excelência. Com certeza voltarei para vê-lo algum dia!",
  ui_story_5065_50650601_1_dialog_content = "Pam, eu já ouvi um pouco sobre seu desempenho no Tribunal de Justiça do Juiz Júnior.",
  ui_story_5065_50650601_2_dialog_content = "O Juiz Júnior queria que você prolongasse sua estadia com ele por mais alguns dias, mas não se preocupe, eu recusei.",
  ui_story_5065_50650601_3_dialog_content = "Como estagiário, sua principal tarefa agora é conhecer a fundo as afiliações sob o Templo de Lumópolis; é isso que suas rotações de função são para.",
  ui_story_5065_50650601_4_dialog_content = "Já pensou em onde gostaria de fazer seu próximo treinamento?",
  ui_story_5065_50650601_5_dialog_content = "Não pensei nisso, já que só estive seguindo suas ordens.",
  ui_story_5065_50650601_6_dialog_content = "Mas se me dessem uma escolha, o lugar onde eu mais quero estudar é claro - dentro do Templo de Lumópolis!",
  ui_story_5065_50650601_7_dialog_content = "Você já ouviu falar da Divisão de Investigação sob o comando direto do Templo de Lumópolis?",
  ui_story_5065_50650601_8_dialog_content = "Você quer dizer o grupo que protege e afirma a fé das pessoas no Deus da Luz?",
  ui_story_5065_50650601_9_dialog_content = "Ouvi dizer que apenas os melhores alunos podem entrar na Divisão de Investigação. E também ouvi... Que você é um deles.",
  ui_story_5065_50650601_10_dialog_content = "Você está por dentro, devo dizer.",
  ui_story_5065_50650601_11_dialog_content = "Neste momento, você tem a oportunidade de ajudar a Divisão de Investigação. Está disposto a tentar?",
  ui_story_5065_50650601_12_dialog_content = "C-Claro! Mas... alguém como eu realmente merece entrar na Divisão de Investigação?",
  ui_story_5065_50650601_13_dialog_content = "A Divisão de Investigação está precisando muito de pessoal ultimamente. Se você se destacar durante a fase de suporte, pode realmente se tornar um membro formal no futuro.",
  ui_story_5065_50650601_14_dialog_content = "Mas devo avisá-lo, os deveres da Divisão de Investigação são muito mais perigosos do que os do Tribunal de Justiça.",
  ui_story_5065_50650601_15_dialog_content = "Com maior perigo, vem maior confiança e honra. Estou disposto a aceitar os riscos!",
  ui_story_5065_50650601_16_dialog_content = "Bom ouvir isso. Ultimamente, houve relatos de membros da True Order promovendo crenças suspeitas e infiltrando-se em Lumópolis.",
  ui_story_5065_50650601_17_dialog_content = "A presença deles representa uma séria ameaça à fé e ao bem-estar dos cidadãos de Lumópolis.",
  ui_story_5065_50650601_18_dialog_content = "Há informações sugerindo que alguns deles se infiltraram na Dawn Academia. Preciso que você me ajude a descobrir suas identidades. Você consegue lidar com essa tarefa?",
  ui_story_5065_50650601_19_dialog_content = "Avante, Noite Branca! Não descansarei até expulsar cada um deles de nossa cidade pura e sagrada!",
  ui_story_5065_50650602_1_dialog_content = "Diante da Verdade, você e eu somos apenas grãos de poeira.",
  ui_story_5065_50650602_2_dialog_content = "Devemos nos arrepender por não compreender a verdade a tempo e por tentar entendê-la.",
  ui_story_5065_50650602_3_dialog_content = "...",
  ui_story_5065_50650602_4_dialog_content = "Saudações. Você veio para aprender sobre a Verdadeira Ordem?",
  ui_story_5065_50650602_5_dialog_content = "Noite Branca lá no alto, você deveria sentir vergonha de si mesmo!",
  ui_story_5065_50650603_1_dialog_content = "Bom trabalho ao tirar aqueles infiltrados da Academia Dawn tão rapidamente! Impressionante!",
  ui_story_5065_50650603_2_dialog_content = "Não é comum alguém obter resultados tão impressionantes em sua primeira tarefa solo, mesmo dentro do Templo de Lumópolis.",
  ui_story_5065_50650603_3_dialog_content = "Mas a situação está longe de ser otimista no momento. Dizem que eles também conseguiram infiltrar-se no Hall da Justiça.",
  ui_story_5065_50650603_4_dialog_content = "Considerando sua experiência anterior no Tribunal de Justiça, você deve saber se orientar por lá.",
  ui_story_5065_50650603_5_dialog_content = "Em seguida, gostaria que você fizesse outra visita ao Hall da Justiça.",
  ui_story_5065_50650604_1_dialog_content = "A beleza deste edifício serve apenas para esconder suas falhas.",
  ui_story_5065_50650604_2_dialog_content = "Assim como as leis que governam Lumópolis, sua grandeza apenas esconde as inúmeras brechas escondidas nelas.",
  ui_story_5065_50650604_3_dialog_content = "... Você não usa também esses espinhos para mostrar o quão poderoso é para os outros?",
  ui_story_5065_50650604_4_dialog_content = "Noite Branca no alto, eu juro encontrar um dono ainda mais adequado para estes espinhos!",
  ui_story_5065_50650701_1_dialog_content = "Pam, o que te traz aqui hoje? Esqueceu alguma coisa?",
  ui_story_5065_50650701_2_dialog_content = "Hoje é um dia de folga.",
  ui_story_5065_50650701_3_dialog_content = "Mas nosso trabalho tem sido tão urgente ultimamente...",
  ui_story_5065_50650701_4_dialog_content = "Sei que as coisas estão bem apertadas agora, mas como estagiário, você não precisa se esforçar tanto por enquanto.",
  ui_story_5065_50650701_5_dialog_content = "Veja, você terá muitos dias ocupados à sua frente no futuro.",
  ui_story_5065_50650701_6_dialog_content = "Ai...",
  ui_story_5065_50650701_7_dialog_content = "Então não se estresse agora.",
  ui_story_5065_50650701_8_dialog_content = "D-De forma alguma! Estou mais do que feliz em dedicar todos os dias da minha vida trabalhando para o Templo de Lumopolis!",
  ui_story_5065_50650701_9_dialog_content = "Você passou por muito recentemente. Aproveite este dia de folga e passe algum tempo com sua família.",
  ui_story_5065_50650702_1_dialog_content = "Pam!",
  ui_story_5065_50650702_2_dialog_content = "Senhora Irridon...? O que é agora?",
  ui_story_5065_50650702_3_dialog_content = "Enquanto cumpria minhas ordens, me envolvi com um grupo de guardas estranhos...",
  ui_story_5065_50650702_4_dialog_content = "Noite Branca no alto, que tipo de desavença eles teriam com um Cavaleiro da Justiça?",
  ui_story_5065_50650702_5_dialog_content = "Não me diga que você os provocou confundindo suas identidades também?",
  ui_story_5065_50650702_6_dialog_content = "Eles não são Guardas Lumo de jeito nenhum! Veja por si mesmo!",
  ui_story_5065_50650702_7_dialog_content = "Proteção! Lealdade! Glória!",
  ui_story_5065_50650702_8_dialog_content = "Huh? Você está certo, tem algo estranho com esses guardas!",
  ui_story_5065_50650702_9_dialog_content = "Ataque!",
  ui_story_5065_50650702_10_dialog_content = "Aqueles guardas... Como eles desapareceram assim?",
  ui_story_5065_50650702_11_dialog_content = "É meio estranho, não é?",
  ui_story_5065_50650702_12_dialog_content = "Agora eu suponho que você vai me dizer que isso só poderia acontecer porque estamos em um mundo dos sonhos, certo?",
  ui_story_5065_50650702_13_dialog_content = "Graças a Deus você está finalmente começando a acreditar em mim, Pam!",
  ui_story_5065_50650702_14_dialog_content = "... Eu não acredito em você. Isso deve ser algum tipo de truque que aprenderam em algum lugar.",
  ui_story_5065_50650702_15_dialog_content = "De qualquer forma, vou relatar esse assunto ao Templo de Lumopolis.",
  ui_story_5065_50650702_16_dialog_content = "...",
  ui_story_5065_50650702_17_dialog_content = "Se:Se me desculpar, senhora', Ladyesponder​​1, demais!",
  ui_story_5065_50650702_18_dialog_content = "Pam...",
  ui_story_5065_50650703_1_dialog_content = "Por que o avô não providenciou alguém para limpar as folhas da frente da casa dele?",
  ui_story_5065_50650703_2_dialog_content = "Deixe-me ajudá-lo a varrê-los.",
  ui_story_5065_50650703_3_dialog_content = "Você... Está me seguindo de novo?!",
  ui_story_5065_50650703_4_dialog_content = "Estou aqui por questões familiares, então a ajuda do Cavaleiro da Justiça não é necessária.",
  ui_story_5065_50650703_5_dialog_content = "Agora, por favor, cuide da sua própria vida!",
  ui_story_5065_50650704_1_dialog_content = "...",
  ui_story_5065_50650704_2_dialog_content = "Por que ainda está aqui, Senhora Irridon?",
  ui_story_5065_50650704_3_dialog_content = "Se você continuar tentando me convencer de que este mundo é apenas um sonho, não terei outra escolha a não ser suspeitar que você seja um membro da Verdadeira Ordem.",
  ui_story_5065_50650704_4_dialog_content = "Eu... Eu não vou mais incomodar você falando disso.",
  ui_story_5065_50650704_5_dialog_content = "Na verdade, comprei alguns ingredientes para fazer comida, mas não sei como prepará-los.",
  ui_story_5065_50650704_6_dialog_content = "Me disseram que você é um excelente cozinheiro, então queria pedir sua ajuda.",
  ui_story_5065_50650704_7_dialog_content = "Essa é realmente a razão pela qual você tem me seguido?",
  ui_story_5065_50650704_8_dialog_content = "... Sim.",
  ui_story_5065_50650704_9_dialog_content = "Hahaha, então você veio à pessoa certa! Aqui, deixe-me ver o que você comprou!",
  ui_story_5065_50650704_10_dialog_content = "Apenas um pouco de farinha e alguns feijões.",
  ui_story_5065_50650704_11_dialog_content = "Esta farinha parece desbotada e suja, os feijões estão encolhidos... Tem certeza de que não foi enganado pela pessoa que os vendeu para você?",
  ui_story_5065_50650704_12_dialog_content = "Ouço dizer que muitas pessoas em Lower Lumopolis só podem pagar por ingredientes como este, então eu também quis experimentá-los.",
  ui_story_5065_50650704_13_dialog_content = "É isso que a nobreza considera na moda agora?",
  ui_story_5065_50650704_14_dialog_content = "Eu só quero ter uma ideia mais clara de como as outras pessoas em Lumópolis vivem.",
  ui_story_5065_50650704_15_dialog_content = "Se eu conseguir encontrar uma maneira de transformar esses ingredientes em algo delicioso, posso compartilhar a receita com todos.",
  ui_story_5065_50650704_16_dialog_content = "... Eu não fazia ideia que você tinha esse lado, Senhora Irridon.",
  ui_story_5065_50650704_17_dialog_content = "Com cuidado e dedicação suficientes, você pode fazer comida deliciosa com qualquer ingrediente. Só um momento, por favor!",
  ui_story_5065_50650704_18_dialog_content = "<color=#e8d9bb>Mais tarde...</color>",
  ui_story_5065_50650704_19_dialog_content = "Desculpe tê-lo deixado esperando! Aqui, experimente!",
  ui_story_5065_50650704_20_dialog_content = "Este sabor... É exatamente igual...",
  ui_story_5065_50650704_21_dialog_content = "Isso tem gosto exatamente como a primeira vez que experimentei!",
  ui_story_5065_50650704_22_dialog_content = "Sério? Que coincidência estranha. Quem fez isso para você da última vez?",
  ui_story_5065_50650704_23_dialog_content = "Mesmo depois de fazer isso, você ainda não se lembra de nada, não é mesmo, Pam?",
  ui_story_5065_50650704_24_dialog_content = "Eu sabia. Você não estava tentando aprender uma nova receita comigo, Senhora Irridon.",
  ui_story_5065_50650704_25_dialog_content = "Ainda preciso ver meu avô, então por favor me perdoe por pedir que você vá embora tão cedo. Além disso...",
  ui_story_5065_50650704_26_dialog_content = "Você deveria tirar um tempo para consultar um médico, Senhora Irridon. Estou muito preocupado com sua saúde mental.",
  ui_story_5065_50650704_27_dialog_content = "Suspirar...",
  ui_story_5065_50650704_28_dialog_content = "Falhei mais uma vez.",
  ui_story_5065_50650704_29_dialog_content = "Você ainda não falhou... Ainda temos outra chance!",
  ui_story_5065_50650704_30_dialog_content = "Apenas não desista!!!",
  ui_story_5065_50650704_31_dialog_content = "... Você está certo. Eu não posso simplesmente desistir assim.",
  ui_story_5065_50650704_32_dialog_content = "Finalmente entendo o quão difícil foi para você me acordar...",
  ui_story_5065_50650704_33_dialog_content = "Mas não se preocupe. Agora sou mais do que capaz de fazer isso.",
  ui_story_5065_50650801_1_dialog_content = "Bom dia, instrutor!",
  ui_story_5065_50650801_2_dialog_content = "Pam, se sentindo melhor depois do descanso?",
  ui_story_5065_50650801_3_dialog_content = "Sinto-me muito",
  ui_story_5065_50650801_4_dialog_content = "Graças à sua ajuda nos últimos dias, eliminamos todos os infiltrados da Ordem Verdadeira dos Jardins de Lumopolis.",
  ui_story_5065_50650801_5_dialog_content = "Mas ainda há sinais de suas atividades além dos Jardins de Lumópolis. Precisamos manter o ritmo e persegui-los.",
  ui_story_5065_50650801_6_dialog_content = "Entendido. Vou ter certeza de expulsar cada um deles!",
  ui_story_5065_50650801_7_dialog_content = "Eles são bons em se esconder, então precisaremos que você faça patrulhas e fique atento.",
  ui_story_5065_50650801_8_dialog_content = "Entendido!",
  ui_story_5065_50650802_1_dialog_content = "Quer saber o segredo por baixo do meu olho direito?",
  ui_story_5065_50650802_2_dialog_content = "Eu prometo a você, junte-se a nós na True Order e descobrirá cada vez mais segredos.",
  ui_story_5065_50650802_3_dialog_content = "... Sobre meu olho direito, ou os ensinamentos sujos desta cidade.",
  ui_story_5065_50650802_4_dialog_content = "Lumópolis é uma cidade pura que nunca cairá. Como poderia ter ensinamentos sujos como você afirma?!",
  ui_story_5065_50650802_5_dialog_content = "Seus delírios não passam de heresias vagas e confusas!",
  ui_story_5065_50650803_1_dialog_content = "Ótimo trabalho, Pam!",
  ui_story_5065_50650803_2_dialog_content = "As ruas do Pátio de Lumopolis estão limpas e serenas novamente, tudo graças a você.",
  ui_story_5065_50650803_3_dialog_content = "Mas esses criminosos aproveitaram a oportunidade para fugir para a Baixa Lumópolis.",
  ui_story_5065_50650803_4_dialog_content = "A população naquele distrito é uma mistura diversa de pessoas, e a fé dos moradores não é forte o suficiente, o que o torna nosso foco principal.",
  ui_story_5065_50650803_5_dialog_content = "Os veteranos da Divisão de Investigação já estão em perseguição em Baixa Lumópolis. Você deveria ir e ajudá-los.",
  ui_story_5065_50650803_6_dialog_content = "Ficaria feliz em trabalhar ao lado dos meus superiores!",
  ui_story_5065_50650804_1_dialog_content = "...",
  ui_story_5065_50650804_2_dialog_content = "Por que você está se encolhendo no canto, senhorita? Está se sentindo mal?",
  ui_story_5065_50650804_3_dialog_content = "Eu... estou bem. Só não tenho como completar a tarefa que me deram...",
  ui_story_5065_50650804_4_dialog_content = "Eles foram gentis comigo e eu realmente queria ajudá-los... Mas eu sou apenas muito inútil.",
  ui_story_5065_50650804_5_dialog_content = "Qual é a sua tarefa? Talvez eu possa ajudá-lo?",
  ui_story_5065_50650804_6_dialog_content = "Foi... para convencer todos a se juntarem à True Order.",
  ui_story_5065_50650804_7_dialog_content = "O quê?!",
  ui_story_5065_50650804_8_dialog_content = "Perdoe-me por tratá-lo tão rudemente... Mas não tenho outra escolha.",
  ui_story_5065_50650901_1_dialog_content = "Pam, aqui está você.",
  ui_story_5065_50650901_2_dialog_content = "Sim. Você tem outra tarefa para mim?",
  ui_story_5065_50650901_3_dialog_content = "Não sou eu; é um professor da Dawn Academia procurando por você. Ele quer que você volte para a escola e ajude.",
  ui_story_5065_50650901_4_dialog_content = "Ele está procurando por mim? Eu me pergunto por quê...?",
  ui_story_5065_50650901_5_dialog_content = "Parece que tem algo a ver com a pesquisa recente dele.",
  ui_story_5065_50650901_6_dialog_content = "Obrigado. Vou retornar à Academia imediatamente!",
  ui_story_5065_50650902_1_dialog_content = "Olá, senhor. Precisa da minha ajuda com algo?",
  ui_story_5065_50650902_2_dialog_content = "Pam, é ótimo ter você de volta!",
  ui_story_5065_50650902_3_dialog_content = "Você pode ter ouvido falar que eu tenho realizado pesquisas sobre \"peso de objetos em diferentes alturas\".",
  ui_story_5065_50650902_4_dialog_content = "Acredito que um objeto seja mais leve nos Jardins de Lumópolis do que na Baixa Lumópolis.",
  ui_story_5065_50650902_5_dialog_content = "Recentemente, minha pesquisa entrou em sua fase empírica final.",
  ui_story_5065_50650902_6_dialog_content = "Se essa hipótese puder ser comprovada, provocará uma onda revolucionária na comunidade acadêmica de Lumópolis!",
  ui_story_5065_50650902_7_dialog_content = "Você sabe por quê?",
  ui_story_5065_50650902_8_dialog_content = "E-Eu não posso dizer que entendo, mas por favor explique!",
  ui_story_5065_50650902_9_dialog_content = "Porque, uma vez comprovada essa hipótese, mostrará que o Deus da Luz retirou um peso significativo dos Jardins de Lumopolis!",
  ui_story_5065_50650902_10_dialog_content = "Isso significa que os Jardins de Lumópolis são mais favorecidos pelo Deus da Luz, e os cidadãos aqui devem receber maior respeito e apoio da população!",
  ui_story_5065_50650902_11_dialog_content = "Em to\n\n\"Em outras  of the original \"game\" and the \" lamasters.ru \n\n Lazen minus tears/ 6 years/ 4 years to hold a and better/  different from the movies and television shows.\n\n on \" .\n\n the of the besth thorn/ 201 Rosal \" dapoxetine on, 3\n",
  ui_story_5065_50650902_12_dialog_content = "Mas sem realizações acadêmicas para mencionar, como eu poderia ajudá-lo?",
  ui_story_5065_50650902_13_dialog_content = "Como estagiário, você tem acesso às estátuas em escala de Lumópolis.",
  ui_story_5065_50650902_14_dialog_content = "Gostaria que você fosse até a entrada do Hall of Justice, o Pátio de Lumópolis e a parte inferior de Lumópolis para medir o peso desta balança de ouro separadamente.",
  ui_story_5065_50650902_15_dialog_content = "Absolutamente sem falsificar ou trapacear. Você entendeu o meu ponto?",
  ui_story_5065_50650902_16_dialog_content = "Entendo, professor. Se as medições mostrarem que o peso dourado é mais pesado em Lumópolis Inferior, então confirma sua hipótese!",
  ui_story_5065_50650902_17_dialog_content = "Que conquista gloriosa é provar a existência das bênçãos do Deus da Luz...",
  ui_story_5065_50650902_18_dialog_content = "Obrigado por me permitir fazer parte deste experimento, professor! Eu vou dar tudo de mim!",
  ui_story_5065_50650903_1_dialog_content = "Então, a única maneira de obter essas medidas é completando uma Missão das Escalas...",
  ui_story_5065_50650903_2_dialog_content = "Mas tudo bem! Eu já tive que completar uma missão parecida antes, então essa não deve ser um problema!",
  ui_story_5065_50650903_3_dialog_content = "Um peso dourado é igual a... três pesos prateados.",
  ui_story_5065_50650903_4_dialog_content = "Bom! Eu deveria fazer anotações claras de todas as minhas descobertas!",
  ui_story_5065_50650904_1_dialog_content = "Hmm, um peso dourado é igual a... Três pesos de prata novamente?",
  ui_story_5065_50650904_2_dialog_content = "Isso provavelmente ocorre porque a diferença de altitude entre os Jardins de Lumópolis e o Pátio de Lumópolis é relativamente pequena...",
  ui_story_5065_50650905_1_dialog_content = "Como isso pode ser...?",
  ui_story_5065_50650905_2_dialog_content = "O peso dourado é igual a três pesos de prata, não importa onde eu vá!!",
  ui_story_5065_50650905_3_dialog_content = "Será que eu medi incorretamente?",
  ui_story_5065_50650905_4_dialog_content = "I-Isso não pode ser, eu segui as instruções para as balanças perfeitamente. Não pode haver erro...",
  ui_story_5065_50650905_5_dialog_content = "Vou ter que relatar minhas descobertas ao professor.",
  ui_story_5065_50650906_1_dialog_content = "O quê?!",
  ui_story_5065_50650906_2_dialog_content = "De jeito nenhum! Como podem os resultados das três medições serem iguais?!",
  ui_story_5065_50650906_3_dialog_content = "É possível que minha teoria esteja falha? Ou poderia haver um problema com os sujeitos do experimento que selecionei? Ou talvez...",
  ui_story_5065_50650906_4_dialog_content = "Talvez a equipe do experimento não seja abençoada pelo Deus da Luz?",
  ui_story_5065_50650906_5_dialog_content = "P-Professor, eu posso garantir que não cometi nenhum erro ao tirar essas medidas...",
  ui_story_5065_50650906_6_dialog_content = "Eu sei, não é culpa sua.",
  ui_story_5065_50650906_7_dialog_content = "Vou analisar mais de perto para descobrir em qual etapa deu errado. Quando eu descobrir, talvez precise da sua ajuda novamente.",
  ui_story_5065_50650906_8_dialog_content = "Você pode voltar por hoje.",
  ui_story_5065_50650906_9_dialog_content = "Muito bem, professor. Tenha um bom dia...",
  ui_story_5065_50651001_1_dialog_content = "Instrutor, você tem outras tarefas para mim?",
  ui_story_5065_50651001_2_dialog_content = "Bem, você chegou na hora certa.",
  ui_story_5065_50651001_3_dialog_content = "Não faz muito tempo, expulsamos alguns membros da True Order que haviam se infiltrado na Baixa Lumópolis.",
  ui_story_5065_50651001_4_dialog_content = "Mas há evidências indicando que eles ainda têm alguns membros escondidos lá, fazendo pregações ilegais.",
  ui_story_5065_50651001_5_dialog_content = "Como eu disse anteriormente, a fé dos moradores de Lower Lumopolis é frágil, tornando-os alvos fáceis para a influência da True Order.",
  ui_story_5065_50651001_6_dialog_content = "Portanto, devemos organizar mais palestras sobre o Deus da Luz em Lumopolis Inferior.",
  ui_story_5065_50651001_7_dialog_content = "Eu analisei seu desempenho na Dawn Academia, então estou confiante em enviá-lo para lá para as devidas funções de palestra.",
  ui_story_5065_50651001_8_dialog_content = "Suas palestras devem ser realizadas na praça da Baixa Lumópolis.",
  ui_story_5065_50651001_9_dialog_content = "Isso... Isso é o que eu sonhei por tanto tempo! Eu prometo que não vou te decepcionar!",
  ui_story_5065_50651002_1_dialog_content = "Desculpe-me... Mas você poderia me indicar a direção da praça em Baixa Lumópolis?",
  ui_story_5065_50651002_2_dialog_content = "Minha querida senhora, o lugar que você procura está bem debaixo dos seus pés!",
  ui_story_5065_50651002_3_dialog_content = "May Eu pergunto se você precisa de ajuda?",
  ui_story_5065_50651002_4_dialog_content = "Obrigado por me informar. Estou aqui para entregar uma série de pequenos sermões.",
  ui_story_5065_50651002_5_dialog_content = "Esta é minha primeira vez falando em público assim, então estou me sentindo um pouco nervoso.",
  ui_story_5065_50651002_6_dialog_content = "Isso é perfeitamente normal.",
  ui_story_5065_50651002_7_dialog_content = "Todos ficam nervosos às vezes, mesmo aqueles que já fizeram milhares de discursos em suas vidas.",
  ui_story_5065_50651002_8_dialog_content = "Você só precisa aprender a aproveitar seu nervosismo. Aprecie a frequência cardíaca elevada e o suor estimulante nas palmas das mãos.",
  ui_story_5065_50651002_9_dialog_content = "Essa mesma estimulação ajudará você a fazer um discurso ainda mais impactante.",
  ui_story_5065_50651002_10_dialog_content = "Apenas estou preocupado que minhas palavras não atraiam a atenção das pessoas.",
  ui_story_5065_50651002_11_dialog_content = "Uma tarefa bastante simples. Permita-me ajudá-lo a reunir um público.",
  ui_story_5065_50651002_12_dialog_content = "Hã?",
  ui_story_5065_50651002_13_dialog_content = "<color=#e8d9bb>Em pouco tempo, a praça se enche de cidadãos de todas as idades, e Pam começa seu ensino tranquilamente.</color>",
  ui_story_5065_50651002_14_dialog_content = "... E assim, concluo os ensinamentos que desejo compartilhar com vocês hoje.",
  ui_story_5065_50651002_15_dialog_content = "Em resumo, desde que seu coração esteja cheio de arrependimento, o Deus da Luz abençoará você com seu divino perdão!",
  ui_story_5065_50651002_16_dialog_content = "Infelizmente, é uma pena que o destino de alguém não possa ser mudado através da fé.",
  ui_story_5065_50651002_17_dialog_content = "O que te faz dizer isso, senhor?",
  ui_story_5065_50651002_18_dialog_content = "...",
  ui_story_5065_50651002_19_dialog_content = "Huh? Espere... Por favor, não vá!",
  ui_story_5065_50651003_1_dialog_content = "Para onde foi aquele senhor mais velho? Eu só queria pedir a ele para compartilhar suas preocupações comigo...",
  ui_story_5065_50651003_2_dialog_content = "Senhoras e senhores!",
  ui_story_5065_50651003_3_dialog_content = "Hã? É aquele homem de bom coração de antes... Ele está dando um discurso aqui também?",
  ui_story_5065_50651003_4_dialog_content = "Há momentos em que as ideologias precisam entrar em conflito para realmente brilhar.",
  ui_story_5065_50651003_5_dialog_content = "E agora, a voz do futuro clama enquanto as marés da Verdade avançam! Todos que acreditarem conhecerão a salvação!",
  ui_story_5065_50651003_6_dialog_content = "Junte-se a nós e seja abençoado com alegria eterna!",
  ui_story_5065_50651003_7_dialog_content = "Você está com a Verdadeira Ordem?",
  ui_story_5065_50651003_8_dialog_content = "Oh não... Ele estava me usando agora mesmo!",
  ui_story_5065_50651101_1_dialog_content = "Ainda há membros da Verdadeira Ordem semeando discórdia em Lumópolis, instrutor?",
  ui_story_5065_50651101_2_dialog_content = "Graças à sua ajuda, a Divisão de Investigação expulsou todos os hereges ativos do nosso meio.",
  ui_story_5065_50651101_3_dialog_content = "Entendo que você deve estar relutante, mas seu treinamento com a Divisão de Investigação está prestes a concluir.",
  ui_story_5065_50651101_4_dialog_content = "É porque meu desempenho não foi satisfatório?",
  ui_story_5065_50651101_5_dialog_content = "Claro nos-translationando a test.",
  ui_story_5065_50651101_6_dialog_content = "Suas habilidades de trabalho são excelentes e você resolveu com sucesso muitos problemas, aliviando a carga de trabalho de seus colegas.",
  ui_story_5065_50651101_7_dialog_content = "Até eu gostaria de mantê-lo na Divisão de Investigação trabalhando assim.",
  ui_story_5065_50651101_8_dialog_content = "No entanto, outra questão para você. Um the Lumopol (2009) and since then, has been working eg  to' and justice.",
  ui_story_5065_50651101_9_dialog_content = "Todos os Cavaleiros Lumo foram mobilizados, mas ainda não descobrimos por que os Eclipsitas estão invadindo.",
  ui_story_5065_50651101_10_dialog_content = "Os Cavaleiros Lumo estão buscando o apoio de estagiários com habilidades de combate. Acredito que você seja a melhor opção para o trabalho.",
  ui_story_5065_50651101_11_dialog_content = "Nossa prioridade máxima no momento é garantir a segurança dos Jardins de Lumópolis.",
  ui_story_5065_50651101_12_dialog_content = "Gostaria que você se reportasse à Capitã da Guarda dos Jardins de Lumopolis e desse uma ajuda a ela. Pam, você está disposta?",
  ui_story_5065_50651101_13_dialog_content = "Não tenho objeções! Mas onde posso encontrar o Capitão da Guarda dos Jardins de Lumópolis?",
  ui_story_5065_50651101_14_dialog_content = "A localização dos Cavaleiros Lumo nesta missão é altamente secreta e não pode ser compartilhada casualmente.",
  ui_story_5065_50651101_15_dialog_content = "Mas ela deixou um enigma para você—",
  ui_story_5065_50651101_16_dialog_content = "Ela está no \"lugar mais próximo do céu.\"",
  ui_story_5065_50651101_17_dialog_content = "Uma charada... Será que ela está me testando?",
  ui_story_5065_50651101_18_dialog_content = "É uma maneira de ver isso. Mas com suas habilidades, você deve ser capaz de encontrar a localização indicada pelo enigma em breve, certo?",
  ui_story_5065_50651101_19_dialog_content = "Eu farei o meu melhor!",
  ui_story_5065_50651102_1_dialog_content = "Saudações! Desculpe-me, mas você é o Capitão da Guarda dos Jardins de Lumópolis?",
  ui_story_5065_50651102_2_dialog_content = "E você é...?",
  ui_story_5065_50651102_3_dialog_content = "Meu nome é Paloma. Sou um iniciante.",
  ui_story_5065_50651102_4_dialog_content = "Você é a Pam, certo? Eu ouvi falar de você através do seu mentor. Parece que essa charada não conseguiu te confundir de jeito nenhum.",
  ui_story_5065_50651102_5_dialog_content = "Parabéns, você gabaritou o primeiro teste.",
  ui_story_5065_50651102_6_dialog_content = "As coisas estão bastante urgentes no momento, então preciso enviar você para verificar a área o mais rápido possível. Espero que esteja tudo bem para você.",
  ui_story_5065_50651102_7_dialog_content = "Eu não me importo mesmo! Estou feliz em começar imediatamente e ajudar a eliminar essa ameaça!",
  ui_story_5065_50651102_8_dialog_content = "Muito bem. Sua missão é relativamente simples—espero que você possa ir à Dawn Academy e investigar se há algum esconderijo dos Eclipsitas lá.",
  ui_story_5065_50651102_9_dialog_content = "A Academia Dawn... Eu não permitirei que nenhum Eclipsita profane os corredores de aprendizado onde eu já estudei!",
  ui_story_5065_50651201_1_dialog_content = "Bom dia, Capitão da Guarda!",
  ui_story_5065_50651201_2_dialog_content = "Bom dia, ouvi dizer que você resgatou um monte de iniciantes dos Eclipsitas?",
  ui_story_5065_50651201_3_dialog_content = "Avante, Noite Branca! Proteger os inocentes e erradicar os Eclipsitas... Eu estava apenas fazendo o que deveria ser feito!",
  ui_story_5065_50651201_4_dialog_content = "Não precisa ser modesto. No começo, eu achei que os elogios do seu mentor eram um pouco exagerados, mas agora vejo que estavam certos.",
  ui_story_5065_50651201_5_dialog_content = "Com base no relatório de patrulha que você enviou, você concluiu que não há esconderijos para os Eclipsitas na Academia Dawn?",
  ui_story_5065_50651201_6_dialog_content = "Embora ainda haja avist counter driv in, ofles and A) a ball of 1While there are still occasional sightings of, it seems that they didn't infiltrate.  de Eclipses 1While there are RT as subject to a vote. 1 1While, it seems that they and 1While in perfectly  ., it seems that they didn. pe (1) 1While… the​",
  ui_story_5065_50651201_7_dialog_content = "Nesse caso, seria um desperdício mantê-lo aqui.",
  ui_story_5065_50651201_8_dialog_content = "Que tal isso? Você vai encontrar o Comandante dos Cavaleiros da Floresta e verificar se há algum esconderijo de Eclipsitas em sua jurisdição.",
  ui_story_5065_50651201_9_dialog_content = "Ela está no \"local de frente para a balança\"...",
  ui_story_5065_50651201_10_dialog_content = "Outro enigma...?",
  ui_story_5065_50651202_1_dialog_content = "Saudações! Desculpe-me, mas você é o Comandante dos Cavaleiros da Floresta?",
  ui_story_5065_50651202_2_dialog_content = "Oi! Você deve ser a Pam!",
  ui_story_5065_50651202_3_dialog_content = "Hmm, você parece ser um bom garoto. Estava ansioso para te conhecer!",
  ui_story_5065_50651202_4_dialog_content = "Por onde devo começar minha investigação, Comandante dos Cavaleiros?",
  ui_story_5065_50651202_5_dialog_content = "Pam, você é bem entusiasmada, não é?",
  ui_story_5065_50651202_6_dialog_content = "Certo, vamos ver... Hmmm, parece que há uma escassez de mão de obra nas residências nobres.",
  ui_story_5065_50651202_7_dialog_content = "Então, Pam, vou precisar que você vá apoiar as patrulhas e investigações lá. E não se esqueça de ficar em segurança!",
  ui_story_5065_50651204_1_dialog_content = "Oh céus! Com sua ajuda, Pam, a investigação realmente ganhou velocidade.",
  ui_story_5065_50651204_2_dialog_content = "Afinal, o esconderijo dos Eclipsitas não fica perto da área residencial, não é? Que alívio.",
  ui_story_5065_50651204_3_dialog_content = "Bem, isso deixa apenas um lugar...",
  ui_story_5065_50651204_4_dialog_content = "A praça perto da escultura em escala, um caminho crucial que leva à Baixa Lumópolis, realmente vale a pena ser explorada.",
  ui_story_5065_50651204_5_dialog_content = "Pam, agora é seu trabalho investigar lá.",
  ui_story_5065_50651301_1_dialog_content = "Suspiro... Isso realmente é uma dor de cabeça...",
  ui_story_5065_50651301_2_dialog_content = "Há algo de errado, Cavaleiro Comandante?",
  ui_story_5065_50651301_3_dialog_content = "Capturamos um Eclipsita que consegue falar Universês e planejamos interrogá-lo detalhadamente sobre como ele se infiltrou em Lumópolis.",
  ui_story_5065_50651301_4_dialog_content = "Mas aquele Eclipsita não diz uma palavra, não importa o quê...",
  ui_story_5065_50651301_5_dialog_content = "Hmm, será que existe algum outro jeito de fazê-lo falar?",
  ui_story_5065_50651301_6_dialog_content = "Nossa! Agora que você mencionou, eu de repente me lembro de um truque popular antigo.",
  ui_story_5065_50651301_7_dialog_content = "Dizem que ao borrifar a Essência de Chattergrass no Peso Dourado e depois pressioná-lo na cabeça do culpado, fará com que ele fale.",
  ui_story_5065_50651301_8_dialog_content = "Não tenho tanta certeza se esse truque vai funcionar nos Eclipsitas.",
  ui_story_5065_50651301_9_dialog_content = "Um peso dourado não deve ser um problema, mas onde posso encontrar a Essência de Chattergrass?",
  ui_story_5065_50651301_10_dialog_content = "Mmm, acredito que os professores da Dawn Academia devem saber como refinar a Essência de Chattergrass.",
  ui_story_5065_50651301_11_dialog_content = "E, para que esse truque funcione, o Peso Dourado deve ser aquele obtido da balança em frente ao Salão da Justiça.",
  ui_story_5065_50651301_12_dialog_content = "Isso não parece muito difícil. Vou te ajudar a olhar!",
  ui_story_5065_50651302_1_dialog_content = "Ufa! Consegui um peso dourado!",
  ui_story_5065_50651302_2_dialog_content = "Agora só falta a Essência de Chattergrass.",
  ui_story_5065_50651302_3_dialog_content = "Certo! Hora de tentar a minha sorte com o professor na Dawn Academia!",
  ui_story_5065_50651303_1_dialog_content = "Pam, por que você está olhando ao redor? Está procurando alguém?",
  ui_story_5065_50651303_2_dialog_content = "Eu estava procurando por você, professor! Você sabe algo sobre a Essência de Chattergrass?",
  ui_story_5065_50651303_3_dialog_content = "Haha, botânica é o meu forte. Você perguntou à pessoa certa.",
  ui_story_5065_50651303_4_dialog_content = "A Essência de Grama Falante é algo que eu tropecei e sintetizei por acaso.",
  ui_story_5065_50651303_5_dialog_content = "Avante, Noite Branca! O Deus da Luz deve ter me guiado até você, docente!",
  ui_story_5065_50651303_6_dialog_content = "Os Cavaleiros Lumo precisam urgentemente dessa essência. Será que eu poderia incomodá-lo para conseguir um pouco?",
  ui_story_5065_50651303_7_dialog_content = "Não é incômodo algum. Se precisar, posso coletar e refinar para você a qualquer momento.",
  ui_story_5065_50651303_8_dialog_content = "O jardim de Chattergrass que eu cuido está cheio de folhas. Não tive tempo de arrumá-lo...",
  ui_story_5065_50651303_9_dialog_content = "Deixe comigo, professor! Eu te ajudo a arrumar!",
  ui_story_5065_50651303_10_dialog_content = "Hmm, muito bem. Você fez um trabalho minucioso na limpeza—muito melhor do que esses juniores pouco confiáveis seus.",
  ui_story_5065_50651303_11_dialog_content = "Aqui, considere esta garrafa de Essência de Chattergrass um presente meu.",
  ui_story_5065_50651303_12_dialog_content = "Sempre que tiver um tempo livre no futuro, passe para me ver e talvez dar uma mãozinha na arrumação do gramado.",
  ui_story_5065_50651304_1_dialog_content = "Nossa, você realmente encontrou os dois?!",
  ui_story_5065_50651304_2_dialog_content = "E você conseguiu fazer isso em tão pouco tempo...",
  ui_story_5065_50651304_3_dialog_content = "Pam, você me fez um grande favor mais uma vez!",
  ui_story_5065_50651304_4_dialog_content = "Suspiro, estou começando a me sentir um pouco relutante em deixá-lo ir.",
  ui_story_5065_50651304_5_dialog_content = "Após o término do seu treinamento, você consideraria se tornar um membro dos Cavaleiros Lumo?",
  ui_story_5065_50651304_6_dialog_content = "Certifique-se de pensar seriamente nisso, tá bom?",
  ui_story_5065_50651401_1_dialog_content = "Ei, Pam, como foi? Descobriu onde os Eclipsitas estão escondidos?",
  ui_story_5065_50651401_2_dialog_content = "Acredito que a situação aqui é extremamente semelhante à que enfrentei nos Jardins de Lumópolis.",
  ui_story_5065_50651401_3_dialog_content = "Embora houvesse vários Eclipsitas desgarrados na área, não encontrei nada que pudesse ser considerado um esconderijo para eles.",
  ui_story_5065_50651401_4_dialog_content = "Já que eles não vieram dos Jardins de Lumopolis ou do Pátio de Lumopolis, só resta uma possibilidade.",
  ui_story_5065_50651401_5_dialog_content = "Eu sei que você tem se esforçado muito nos últimos dias.",
  ui_story_5065_50651401_6_dialog_content = "Mas agora, ainda preciso que você ajude o Comandante dos Cavaleiros da Água em Baixa Lumópolis.",
  ui_story_5065_50651401_7_dialog_content = "Se os Eclipsitas realmente estão escondidos na Baixa Lumópolis, estou um pouco preocupado com ela lá sozinha.",
  ui_story_5065_50651401_8_dialog_content = "E, claro, não deixe ela saber o que eu acabei de dizer.",
  ui_story_5065_50651401_9_dialog_content = "Ah, quase me esqueci de te dizer que o Comandante dos Cavaleiros da Água está no \"lugar entre dois olhos verdes.\"",
  ui_story_5065_50651401_10_dialog_content = "Entendido. Vou encontrar a Comandante dos Cavaleiros da Água e ajudá-la a destruir os Eclipsitas e seu ponto de encontro escondido!",
  ui_story_5065_50651402_1_dialog_content = "Hã?",
  ui_story_5065_50651402_2_dialog_content = "E aí, moça? Por que está me olhando de forma estranha? Tem algo te incomodando?",
  ui_story_5065_50651402_3_dialog_content = "Estou no lugar certo? Ou será que... Você é o Comandante dos Cavaleiros da Água?",
  ui_story_5065_50651402_4_dialog_content = "Sim, eu sou.",
  ui_story_5065_50651402_5_dialog_content = "Ah-ha, entendi agora! Você deve ser a pessoa que eles mencionaram - Pam! Bom finalmente te conhecer!",
  ui_story_5065_50651402_6_dialog_content = "Realmente há uma escassez de pessoal na Baixa Lumópolis no momento, então talvez eu precise incomodá-lo com uma patrulha externa...",
  ui_story_5065_50651402_7_dialog_content = "Sem problemas! Se precisar que eu patrulhe uma área, é só me dar a ordem!",
  ui_story_5065_50651402_8_dialog_content = "Deixe-me ver... a única área residencial que ainda não foi verificada fica perto da escultura em escala. Então é lá que você precisa patrulhar!",
  ui_story_5065_50651402_9_dialog_content = "Sem problema!",
  ui_story_5065_50651403_1_dialog_content = "Há mais Eclipsitas aqui do que nos Jardins de Lumópolis, e eles são muito mais fortes também.",
  ui_story_5065_50651403_2_dialog_content = "Será que o ponto de encontro secreto deles está em algum lugar próximo?",
  ui_story_5065_50651404_1_dialog_content = "Roooor!",
  ui_story_5065_50651404_2_dialog_content = "Este é o fim!",
  ui_story_5065_50651404_3_dialog_content = "Ufa... Eu nunca esperava que os Eclipsitas estivessem escondidos em uma casa normal como esta.",
  ui_story_5065_50651404_4_dialog_content = "...",
  ui_story_5065_50651404_5_dialog_content = "Quem está aí? Mostre-se!",
  ui_story_5065_50651404_6_dialog_content = "Vou com tudo contra você!!!",
  ui_story_5065_50651404_7_dialog_content = "É você!",
  ui_story_5065_50651404_8_dialog_content = "... Você me conhece?",
  ui_story_5065_50651404_9_dialog_content = "Você não se lembra? Quando eu estava pregando meus sermões na praça da cidade outro dia, você disse...",
  ui_story_5065_50651404_10_dialog_content = "Infelizmente, é uma pena que o destino de alguém não possa ser mudado através da fé.",
  ui_story_5065_50651404_11_dialog_content = "Na época, eu realmente queria perguntar por que você disse uma coisa dessas e o que você estava disposto a fazer a respeito, mas você saiu com tanta pressa...",
  ui_story_5065_50651404_12_dialog_content = "(tosse) E agora você vê.",
  ui_story_5065_50651404_13_dialog_content = "Sim... Sou eu quem escondeu os Eclipsitas em minha casa! Eu quero me vingar de Lumópolis! Vamos lá! Execute-me! Tosse...",
  ui_story_5065_50651404_14_dialog_content = "Você está machucado? Por favor, me perdoe, eu não te machuquei agora há pouco, machuquei?",
  ui_story_5065_50651404_15_dialog_content = "Pare de ser tão hipócrita, tosse... P-Por que você quer me curar?",
  ui_story_5065_50651404_16_dialog_content = "Eu não sei o que aconteceu no seu passado, nem sei por que você deseja se vingar de Lumópolis.",
  ui_story_5065_50651404_17_dialog_content = "Mas você ainda é meu compatriota! Um cidadão vivo e respirando!",
  ui_story_5065_50651404_18_dialog_content = "Avante, Noite Branca! O Deus da Luz nos ensina a amar e ajudar nossos concidadãos e a demonstrar compaixão...",
  ui_story_5065_50651404_19_dialog_content = "Eu não vou ficar de braços cruzados e assistir enquanto você sofre!",
  ui_story_5065_50651404_20_dialog_content = "Quem é você, de verdade?",
  ui_story_5065_50651404_21_dialog_content = "Meu nome é Paloma, mas pode me chamar de Pam. Sou uma iniciante do templo.",
  ui_story_5065_50651404_22_dialog_content = "Heh... Então, parece que crianças inocentes e de bom coração como você realmente existem neste mundo.",
  ui_story_5065_50651404_23_dialog_content = "Se eu tivesse conhecido pessoas tão verdadeiras quanto você naquela época, talvez eu não teria chegado a este ponto hoje...",
  ui_story_5065_50651404_24_dialog_content = "No entanto, criança, em uma cidade como esta, inocência e bondade não te levam longe.",
  ui_story_5065_50651404_25_dialog_content = "Espero que você... não enfrente a mesma injustiça que eu enfrentei...",
  ui_story_5065_50651404_26_dialog_content = "O-o que você está planejando fazer?",
  ui_story_5065_50651404_27_dialog_content = "Obrigado por me permitir sentir um pouco de calor nos momentos finais da minha vida.",
  ui_story_5065_50651404_28_dialog_content = "Adeus, garoto.",
  ui_story_5065_50651404_29_dialog_content = "<color=#e8d9bb>O velhote alcança sua cintura e puxa uma adaga, cravando-a violentamente em seu próprio coração.</color>",
  ui_story_5065_50651404_30_dialog_content = "...!!!",
  ui_story_5065_50651404_31_dialog_content = "Por quê... Por que você faria isso...?",
  ui_story_5065_50651501_1_dialog_content = "Pam... Q-Que coincidência!",
  ui_story_5065_50651501_2_dialog_content = "(Suspiro, você é um péssimo mentiroso, Irridon...)",
  ui_story_5065_50651501_3_dialog_content = "Senhora Irridon? O que você está fazendo aqui também...?",
  ui_story_5065_50651501_4_dialog_content = "Eu... Estou aqui para trabalhar, é claro! Os Cavaleiros da Justiça são conhecidos por correr assim de vez em quando.",
  ui_story_5065_50651501_5_dialog_content = "U-Infelizmente, eu perdi um arquivo muito importante e agora estou desesperadamente procurando por ele.",
  ui_story_5065_50651501_6_dialog_content = "Dizem que você é muito habilidosa em encontrar itens perdidos, Pam... Poderia me ajudar a procurar?",
  ui_story_5065_50651501_7_dialog_content = "Um arquivo muito importante?",
  ui_story_5065_50651501_8_dialog_content = "Sim! É extremamente importante! Se eu não encontrar, eles podem me expulsar do Hall da Justiça!",
  ui_story_5065_50651501_9_dialog_content = "Suspiro, se é realmente tão importante, você deveria ter cuidado melhor disso desde o início.",
  ui_story_5065_50651501_10_dialog_content = "Onde você esteve recentemente?",
  ui_story_5065_50651501_11_dialog_content = "Bem, eu acabei de vir até aqui daquela estátua das balanças.",
  ui_story_5065_50651501_12_dialog_content = "... Muito bem, vou te ajudar.",
  ui_story_5065_50651502_1_dialog_content = "Ah, por que alguém jogaria tanto papel picado em uma rua tão limpa e organizada?",
  ui_story_5065_50651502_2_dialog_content = "Espere, será que aquele arquivo está escondido em algum lugar debaixo de todo esse papel?",
  ui_story_5065_50651502_3_dialog_content = "Não posso descartar nenhuma possibilidade, então terei que dar uma boa limpeza neste lugar!",
  ui_story_5065_50651502_4_dialog_content = "Não há nada aqui...",
  ui_story_5065_50651502_5_dialog_content = "Suponho que vou ter que continuar olhando para frente.",
  ui_story_5065_50651503_1_dialog_content = "Por que ninguém limpou todas essas folhas também?",
  ui_story_5065_50651503_2_dialog_content = "Aff... Ainda não consigo descartar todas as possibilidades.",
  ui_story_5065_50651503_3_dialog_content = "Limpar essas folhas não deve demorar muito mesmo.",
  ui_story_5065_50651503_4_dialog_content = "Ufa! Bem mais limpo!",
  ui_story_5065_50651503_5_dialog_content = "Mas ainda sem sinal daquele arquivo...",
  ui_story_5065_50651504_1_dialog_content = "Graças a Deus! Este deve ser o arquivo que estava faltando!",
  ui_story_5065_50651504_2_dialog_content = "Mas estava bem à vista, perto da estátua das balanças... Como a Senhora Irridon poderia ter perdido isso?",
  ui_story_5065_50651505_1_dialog_content = "Senhora Irridon, este é o arquivo que estava faltando?",
  ui_story_5065_50651505_2_dialog_content = "... Você por acaso deu uma olhada no conteúdo?",
  ui_story_5065_50651505_3_dialog_content = "Eu posso não ser oficialmente empregado pelo Tribunal de Justiça, mas até eu sei que olhar arquivos pessoais é inaceitável.",
  ui_story_5065_50651505_4_dialog_content = "Acredito que você deve ser o responsável por verificar isso.",
  ui_story_5065_50651505_5_dialog_content = "Não deve ser um problema. Na verdade, eu estava esperando que você desse uma olhada mais de perto no arquivo.",
  ui_story_5065_50651505_6_dialog_content = "M-Me...? Mas por quê?",
  ui_story_5065_50651505_7_dialog_content = "Só abrir e ver!",
  ui_story_5065_50651505_8_dialog_content = "\"A família Pyrrhus, em conjunto com a família Gautier, utilizou Eclipsitas aprimorados para realizar uma rebelião violenta...\"",
  ui_story_5065_50651505_9_dialog_content = "\"Cada membro de suas respectivas famílias foi condenado à morte. Em caso de mais resistência, eles serão executados no local?!\"",
  ui_story_5065_50651505_10_dialog_content = "Deve haver algum erro, Senhora Irridon!!",
  ui_story_5065_50651505_11_dialog_content = "Pam, você não acha... Que já viu um veredicto como este antes?",
  ui_story_5065_50651505_12_dialog_content = "E-Eu já? Parece que já vi isso antes, mas onde? Espere... Você está tentando colocar essa ideia na minha cabeça, não está?",
  ui_story_5065_50651505_13_dialog_content = "Você nunca realmente perdeu esse arquivo! Você queria que eu o encontrasse e lesse, não é?",
  ui_story_5065_50651505_14_dialog_content = "Por favor, pare de tentar evitar isso, Pam. Tudo já deve estar perfeitamente claro em sua mente agora, não é?",
  ui_story_5065_50651505_15_dialog_content = "Senhora Irridon, eu não temo nem dificuldades nem humilhação...",
  ui_story_5065_50651505_16_dialog_content = "Mas eu não vou permitir que você faça uma chacota da minha família!",
  ui_story_5065_50651505_17_dialog_content = "Pam...",
  ui_story_5065_50651505_18_dialog_content = "Realmente não há como fazê-la aceitar a realidade?",
  ui_story_5065_50651505_19_dialog_content = "Eu entendo ela muito bem. Perder-se nestes dias cheios de esperança em sua vida deve trazer a ela muito conforto e felicidade.",
  ui_story_5065_50651505_20_dialog_content = "Mas pelo Deus da Luz, juro que nunca desistirei dela.",
  ui_story_5065_50651505_21_dialog_content = "Se uma vez não for suficiente, então vou continuar tentando de novo e de novo. Não importa quantas vezes seja necessário...",
  ui_story_5065_50651505_22_dialog_content = "Teremos sucesso um dia.",
  ui_story_5065_50651505_23_dialog_content = "Mesmo que isso signifique... Tornar-nos inimigos novamente.",
  ui_story_5065_50651601_1_dialog_content = "Pam!",
  ui_story_5065_50651601_2_dialog_content = "Comandante dos Cavaleiros... Me desculpe!",
  ui_story_5065_50651601_3_dialog_content = "Por que você está pedindo desculpas?",
  ui_story_5065_50651601_4_dialog_content = "Durante minha última missão, eu... Eu não consegui impedir o suspeito de tirar a própria vida e não consegui entender seus motivos para esconder Eclipsitas em sua casa.",
  ui_story_5065_50651601_5_dialog_content = "Encontrar o culpado já é impressionante. Deixe o resto para o Tribunal de Justiça.",
  ui_story_5065_50651601_6_dialog_content = "Mas agora, há uma tarefa ainda mais urgente para você.",
  ui_story_5065_50651601_7_dialog_content = "Com base em nossa investigação, seu mentor está envolvido em traição. Temos provas sólidas e precisamos prendê-la imediatamente!",
  ui_story_5065_50651601_8_dialog_content = "No entanto, seu mentor é um dos membros mais habilidosos da Divisão de Investigação. É arriscado agir sem um plano sólido.",
  ui_story_5065_50651601_9_dialog_content = "E você, como trainee designado dela, tem um motivo válido para se aproximar dela...",
  ui_story_5065_50651601_10_dialog_content = "Você quer que eu... Prenda meu instrutor?",
  ui_story_5065_50651601_11_dialog_content = "Esta missão é, sem dúvida, desafiadora. Mas se você não fizer isso, pode acabar parecendo um cúmplice...",
  ui_story_5065_50651601_12_dialog_content = "Você realmente conseguiu encontrar evidências suficientes para incriminá-la? Este mandado de prisão... Foi aprovado pelo Senhor da Cidade?",
  ui_story_5065_50651601_13_dialog_content = "Claro, posso verificar tudo o que você mencionou, um por um.",
  ui_story_5065_50651601_14_dialog_content = "Mas primeiro, você precisa me dizer, está dentro ou fora desta missão?",
  ui_story_5065_50651601_15_dialog_content = "Avante, Noite Branca! Se meu instrutor é realmente culpado de crimes tão hediondos...",
  ui_story_5065_50651601_16_dialog_content = "Então, tenho a obrigação de prendê-la!",
  ui_story_5065_50651602_1_dialog_content = "Pam, qual é o problema? Você geralmente não parece tão preocupada.",
  ui_story_5065_50651602_2_dialog_content = "... Como você pôde fazer algo assim?",
  ui_story_5065_50651602_3_dialog_content = "Hã?",
  ui_story_5065_50651602_4_dialog_content = "Estou grato pela orientação que você me ofereceu nestes últimos dias, mas...",
  ui_story_5065_50651602_5_dialog_content = "Por favor, me perdoe! Não tenho escolha a não ser te recompensar dessa maneira!",
  ui_story_5065_50651602_6_dialog_content = "Espere! ESPERE!",
  ui_story_5065_50651602_7_dialog_content = "Caramba, alguns movimentos gentis seriam suficientes. Por que ir com tudo?",
  ui_story_5065_50651602_8_dialog_content = "Mesmo que eu possa salvar vidas, você não pode ser tão imprudente.",
  ui_story_5065_50651602_9_dialog_content = "Desculpe, eu queria aproveitar essa oportunidade para testar as habilidades de combate da Pam.",
  ui_story_5065_50651602_10_dialog_content = "Parabéns, você passou na avaliação da etapa atual!",
  ui_story_5065_50651602_11_dialog_content = "Avaliação? Então... Você nunca estava planejando traição? Mas e aquele mandado de prisão e todas aquelas evidências?",
  ui_story_5065_50651602_12_dialog_content = "Todos eram falsos, sabe. Seu mentor vai te ensinar como identificar os verdadeiros mandados de prisão no futuro!",
  ui_story_5065_50651602_13_dialog_content = "Ahem, mas não foi nossa intenção enganar você, sabe.",
  ui_story_5065_50651602_14_dialog_content = "O Templo de Lumópolis estabeleceu este formato de avaliação para ver se você deixaria as emoções atrapalharem...",
  ui_story_5065_50651602_15_dialog_content = "Sua habilidade de deixar de lado emoções pessoais diante de decisões importantes e manter sua posição é exatamente a qualidade que o pessoal do Templo de Lumópolis precisa.",
  ui_story_5065_50651602_16_dialog_content = "Passar nesta avaliação significa que você está um passo mais perto de trabalhar no Templo de Lumópolis.",
  ui_story_5065_50651602_17_dialog_content = "Ah, graças à Luz! Estou tão aliviado que você não é realmente um traidor!",
  ui_story_5065_50651602_18_dialog_content = "Mas...",
  ui_story_5065_50651602_19_dialog_content = "O que devo fazer se houver algo errado com minhas ordens, ou com um julgamento ou mandado de prisão, por exemplo?",
  ui_story_5065_50651602_20_dialog_content = "Sh-Devo continuar carregando-os assim, sem questionar?",
  ui_story_5065_50651602_21_dialog_content = "As decisões do Templo de Lumopolis representam a vontade do Deus da Luz. Há muitos níveis de supervisão antes que as ordens sejam emitidas.",
  ui_story_5065_50651602_22_dialog_content = "I-É mesmo...",
  ui_story_5065_50651602_23_dialog_content = "Fique tranquilo, as coisas que você está preocupado não vão acontecer.",
  ui_story_5065_50651602_24_dialog_content = "Em vez de se preocupar com todos esses \"e se\", você pode simplesmente perguntar ao seu mentor mais sobre sua futura carreira.",
  ui_story_5065_50651602_25_dialog_content = "... Entendido!",
  ui_story_5065_50651602_26_dialog_content = "Se eu realmente me tornar um estudioso no futuro, dedicarei minha vida inteira a servir o Deus da Luz!",
  ui_story_5065_50651602_27_dialog_content = "Através das minhas ações, levarei a luz a todas as casas de Lumópolis e protegerei nosso lindo lar!",
  ui_story_5065_50651602_28_dialog_content = "Ótimo, mal posso esperar para ver o dia em que você se torne uma freira oficial.",
  ui_story_5065_50651602_29_dialog_content = "Mas no próximo período de aprendizado, você enfrentará muitos desafios, então é preciso manter-se atento.",
  ui_story_5065_50651602_30_dialog_content = "Obrigado por me lembrar! Prometo que vou me esforçar ainda mais para completar todos os desafios que estão à minha frente!",
  ui_story_5065_50651701_1_dialog_content = "Estou imaginando coisas? Por que parece que estou constantemente encontrando as mesmas pessoas e realizando as mesmas tarefas...",
  ui_story_5065_50651701_2_dialog_content = "Estou tão tonto e realizar minhas tarefas está ficando ainda mais exaustivo...",
  ui_story_5065_50651701_3_dialog_content = "Há quanto tempo sou um iniciante? Quanto tempo falta para eu terminar?",
  ui_story_5065_50651701_4_dialog_content = "Por que ainda não fui promovida? Será que... Será que é porque ainda não tenho habilidades suficientes para me tornar uma verdadeira freira?",
  ui_story_5065_50651701_5_dialog_content = "Ou isso poderia realmente ser...",
  ui_story_5065_50651701_6_dialog_content = "Um sonho?",
  ui_story_5065_50651701_7_dialog_content = "Senhora Irridon?!",
  ui_story_5065_50651701_8_dialog_content = "Seja sincero, você percebeu o quão estranho é este mundo há muito tempo, não é?",
  ui_story_5065_50651701_9_dialog_content = "Mas você estava relutante em encarar a verdade todo esse tempo. Não é verdade?",
  ui_story_5065_50651701_10_dialog_content = "N-Não... Eu só queria trabalhar duro e ganhar a aprovação do meu instrutor para me tornar uma freira do Templo de Lumópolis. Eu só...",
  ui_story_5065_50651701_11_dialog_content = "Eu só queria poupar minha família de ainda mais dor!",
  ui_story_5065_50651701_12_dialog_content = "\"Ainda mais dor\"?",
  ui_story_5065_50651701_13_dialog_content = "Ah, o quê que eu tô falando...? Minha família deve estar segura e protegida no Pátio de Lumópolis agora mesmo...",
  ui_story_5065_50651701_14_dialog_content = "Mas por que parece que faz séculos que não os vejo...?",
  ui_story_5065_50651701_15_dialog_content = "Por que eu continuo vendo imagens deles sendo presos na minha mente...?",
  ui_story_5065_50651701_16_dialog_content = "Essas imagens devem ser os verdadeiros pesadelos aqui, certo Senhora Irridon?",
  ui_story_5065_50651701_17_dialog_content = "É hora de encarar a realidade, Pam.",
  ui_story_5065_50651701_18_dialog_content = "... Esse mundo é realmente apenas uma ilusão?",
  ui_story_5065_50651701_19_dialog_content = "Mas meu sonho está tão perto de se realizar! Só mais um pouco e finalmente poderei me tornar uma verdadeira freira!",
  ui_story_5065_50651701_20_dialog_content = "Se eu acordar agora... Tudo isso vai desaparecer?",
  ui_story_5065_50651701_21_dialog_content = "Sinto muito, Pam...",
  ui_story_5065_50651701_22_dialog_content = "... Aquele arquivo que você me mostrou também era real?",
  ui_story_5065_50651701_23_dialog_content = "Em outras palavras, se eu acordar desse sonho, minha família não estará mais comigo...",
  ui_story_5065_50651701_24_dialog_content = "Se for esse o caso, então por que se preocupar em acordar? Eu nunca conseguiria sobreviver sozinho.",
  ui_story_5065_50651701_25_dialog_content = "Não, Pam. Você é muito mais forte do que imagina.",
  ui_story_5065_50651701_26_dialog_content = "Fora deste mundo dos sonhos, você é mais forte, mais confiante e totalmente consciente de quem realmente é.",
  ui_story_5065_50651701_27_dialog_content = "Você vai sobreviver e a vida que você terá será muito mais maravilhosa do que você pode imaginar.",
  ui_story_5065_50651701_28_dialog_content = "Então ainda somos amigos no mundo real?",
  ui_story_5065_50651701_29_dialog_content = "... Vivemos em dois mundos diferentes lá fora, e o espaço entre eles é ainda maior do que o espaço entre este sonho e a realidade.",
  ui_story_5065_50651701_30_dialog_content = "Mas eu sempre admirei a Pam que vive nos seus próprios termos, mesmo em um mundo separado.",
  ui_story_5065_50651701_31_dialog_content = "Ela ousa amar e odiar, e é muito mais forte do que alguém preso a um lugar como eu.",
  ui_story_5065_50651701_32_dialog_content = "Se essas tragédias não tivessem acontecido no passado, tenho certeza de que poderíamos ter sido bons amigos.",
  ui_story_5065_50651701_33_dialog_content = "Mas somos bons amigos!",
  ui_story_5065_50651701_34_dialog_content = "E-Eu estou começando a lembrar das coisas. Ainda estão tão distantes, mas são reais.",
  ui_story_5065_50651701_35_dialog_content = "Nessas memórias, concordamos em ser amigos. É por isso que você tem se esforçado tanto para me acordar desse sonho, não é?",
  ui_story_5065_50651701_36_dialog_content = "Mesmo que este mundo inteiro seja uma mentira, nossa amizade... é muito real!",
  ui_story_5065_50651701_37_dialog_content = "...",
  ui_story_5065_50651701_38_dialog_content = "Isso mesmo. Nunca vou esquecer que você foi meu primeiro amigo.",
